local function l1o01O10l1lo0oO0O(a, b)
	local r, m = 0, 1
	for _ = 1, 8 do
		local aa, bb = a % 2, b % 2
		if aa ~= bb then r = r + m end
		a = (a - aa) / 2; b = (b - bb) / 2; m = m * 2
	end
	return r
end
